describe('Payment Flow - Total Price Update', () => {
    beforeEach(() => {
        cy.visit('/checkout'); // Adjust the URL to your application's checkout page
    });

    it('should update the total price when quantity is increased', () => {
        cy.get('.quantity-input').clear().type('2'); // Assuming the quantity input has a class of 'quantity-input'
        cy.get('.update-button').click(); // Assuming there is an update button to recalculate the total
        cy.get('.total-price').should('contain', '$40.00'); // Adjust the expected total price accordingly
    });

    it('should not allow quantity to be less than 1', () => {
        cy.get('.quantity-input').clear().type('0'); // Trying to set quantity to 0
        cy.get('.update-button').click();
        cy.get('.error-message').should('be.visible').and('contain', 'Quantity must be at least 1'); // Adjust the error message accordingly
    });
});
